import { Button, CModal, useMaskableOnOkGuard } from '@cloud-materials/common';
import React, { useState } from 'react';
import DemoContainerJustForDemo from './DemoContainerJustForDemo';

const ClickMe = () => {
  const CloseCount = 5;
  const [count, setCount] = useState(0);
  useMaskableOnOkGuard(async () => {
    if (count >= CloseCount) {
      await new Promise(resolve => setTimeout(resolve, 1e3));

      return true;
    }
    return false;
  });

  return (
    <div onClick={() => setCount(count + 1)}>
      你需要点 <b>{CloseCount}</b> 次才能点“确认”按钮关闭我，你已经点了{count}次
    </div>
  );
};

